//const keywords = keywordString.split(",").map(k => k.trim().toLowerCase());
// Keywords are now carried on every item — read directly, no node reference needed
const keywordString = $('Loop Over Items').first()?.json?.userKeywords ||
  "US,Foreign,China,EU,Russia,Policy,Diplomacy,Deal,Trade,Tariff,meeting,BRICS,UN,War";

const keywords = keywordString.split(",").map(k => k.trim().toLowerCase());

// Step 1: Score each item
const scoredItems = items.map(item => {
  const content = (item.json.content || "").toLowerCase();
  const title = (item.json.title || "").toLowerCase();

  let titleHits = 0;
  let contentHits = 0;

  for (const keyword of keywords) {
    const titleMatch = (title.match(new RegExp(`\\b${keyword}\\b`, "g")) || []).length;
    const contentMatch = (content.match(new RegExp(`\\b${keyword}\\b`, "g")) || []).length;

    titleHits += titleMatch;
    contentHits += contentMatch;
  }

  const relevanceScore = titleHits * 2 + contentHits;

  return {
    json: {
      ...item.json,
      titleHits,
      contentHits,
      relevanceScore
    }
  };
});

// Step 2: Sort by relevanceScore descending
const sorted = scoredItems.sort((a, b) => b.json.relevanceScore - a.json.relevanceScore);

// Step 3: Return top 1
return sorted.slice(0, 1);

return items.map((item, index) => {
  const html = item.json.data || "";

  // Step 1: Clean noisy tags
  let cleanHtml = html
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<nav[\s\S]*?<\/nav>/gi, '')
    .replace(/<footer[\s\S]*?<\/footer>/gi, '')
    .replace(/<aside[\s\S]*?<\/aside>/gi, '')
    .replace(/<header[\s\S]*?<\/header>/gi, '')
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, '');

  // Step 2: Try to extract content from <article> or common classes
  let match = cleanHtml.match(/<article[\s\S]*?<\/article>/i);

  if (!match) {
    match = cleanHtml.match(/<div[^>]*class="[^"]*(article-body|content|main-content)[^"]*"[^>]*>([\s\S]*?)<\/div>/i);
  }

  const articleHtml = match ? match[0] : cleanHtml;

  // Step 3: Strip all remaining tags
  const plainText = articleHtml
    .replace(/<[^>]+>/g, '')      // Remove all tags
    .replace(/\s{2,}/g, ' ')      // Collapse whitespace
    .trim();

  // Step 4: Fetch corresponding metadata from another node (Code1)
  const meta = $items('Code1', 0)[index].json;

  return {
    json: {
      title: meta.title || '',
      link: meta.link || '',
      pubDate: meta.pubDate || '',
      content: plainText
    }
  };
});

const categoryId = [3];

return items.map((item, index) => {
  const htmlText = item.json.text || "";

  // Extract the title
  const titleMatch = htmlText.match(/<title>(.*?)<\/title>/s);
  const title = titleMatch ? titleMatch[1].trim() : "Untitled Article";

  // Extract content
  const contentMatch = htmlText.match(/<content>([\s\S]*?)<\/content>/);
  const content = contentMatch ? contentMatch[1].trim() : "";

  // Extract tags
  const tagsMatch = htmlText.match(/<tags>(.*?)<\/tags>/s);
  const rawTags = tagsMatch ? tagsMatch[1].trim() : "";
  const tagList = rawTags.split(',').map(tag => tag.trim()).filter(tag => tag.length > 0);

  // ✅ Pull link directly from Code3 — bypasses LLM completely
  const link = $('Code3').first().json.link || "";

  return {
    json: {
      title,
      content,
      category: categoryId,
      tags: tagList,
      link
    }
  };
});

// Re-attach userKeywords from the feed item onto each article item
// Loop Over Items passes the original feed item as context
const userKeywords = $('Loop Over Items').first()?.json?.userKeywords ||
  "US,Foreign,China,EU,Russia,Policy,Diplomacy,Deal,Trade,Tariff,meeting,BRICS,UN,War";

return items.map(item => ({
  json: {
    ...item.json,
    userKeywords
  }
}));
